Note there are multiple axios async calls on this page, `axios.get()` and `axios.delete()` don't seem to cause any problems but `axios.post()` causes the error. I'm also running`await axios.post()` from a for loop, which isn't best practices so could be a special case?

```
import React, { useState, useCallback, useEffect, ReactNode } from 'react'
import { Box, Flex, Button, useToast, Divider, useDisclosure, Badge } from '@chakra-ui/react'

import Card from '@src/components/Card'
import CardHeader from '@src/components/CardHeader'
import axios, { generateHeaders } from '@src/utils/axios'
import * as routes from '@src/utils/expressRoutes'
import { useForm } from 'react-hook-form'
import OnePagersCSVUploadModal from '@src/components/Modals/Boards/OnePagersCSVUploadModal'
import { FaArrowUp } from 'react-icons/fa'
import OnePagerBoardRowCard from '@src/components/onePagerBoardRowCard'
import ControlledTextInput from '@src/components/Input/ControlledTextInput'
import { APP_URL } from '@src/utils/config'
import { PUBLISHED_BOARD_ONEPAGER } from '@src/types/boards'
import AddOnePagersModal, { AddOnePagersModalProps } from './AddOnePagersModal'
import BoardJoinRequestsModal from './BoardJoinRequestsModal'

const SIMPLE_APP_URL = APP_URL!.replace(/http:\/\/|https:\/\//, '')

export enum BOARD_JOIN_REQUEST_STATUS {
  REQUESTED = 'requested',
  APPROVED = 'approved',
  REJECTED = 'rejected',
  IGNORED = 'ignored',
}

export const RequestStatusBadgeMap = new Map<BOARD_JOIN_REQUEST_STATUS, ReactNode>([
  [BOARD_JOIN_REQUEST_STATUS.APPROVED, <Badge colorScheme="green">APPROVED</Badge>],
  [BOARD_JOIN_REQUEST_STATUS.REJECTED, <Badge colorScheme="red">REJECTED</Badge>],
  [BOARD_JOIN_REQUEST_STATUS.REQUESTED, <Badge colorScheme="orange">PENDING</Badge>],
  [BOARD_JOIN_REQUEST_STATUS.IGNORED, <Badge colorScheme="orange">IGNORED</Badge>],
])

export interface RequestToJoinBoard {
  onepager: any
  status: BOARD_JOIN_REQUEST_STATUS
}

export interface AvailableOnePagersProps {
  boardUuid: string
  allOpsOnBoard: PUBLISHED_BOARD_ONEPAGER[]
  setOnePagersOnBoard: (onePagers: any[]) => void
  showSearch?: boolean
}

const AvailableOnePagers: React.FC<AvailableOnePagersProps> = ({
  boardUuid,
  allOpsOnBoard,
  setOnePagersOnBoard,
  showSearch,
}) => {
  const [openModal, setOpenModal] = useState<boolean>(false)
  const [joinRequests, setJoinRequests] = useState<RequestToJoinBoard[]>([])
  const [newJoinRequests, setNewJoinRequests] = useState<number>(0)
  const { isOpen, onOpen, onClose } = useDisclosure()
  const {
    isOpen: isJoinRequestsModalOpen,
    onOpen: onJoinRequestsModalOpen,
    onClose: onJoinRequestsModalClose,
  } = useDisclosure()
  const toast = useToast()

  const { handleSubmit, control } = useForm()

  const loadOnePagerJoinRequests = useCallback(async (): Promise<void> => {
    try {
      const response = await axios.get(routes.boardOnepagersJoinRequests(boardUuid), { headers: generateHeaders() })
      const { requests }: { requests: RequestToJoinBoard[] } = response.data.data
      setJoinRequests(requests)
      setNewJoinRequests(
        requests.filter((request: RequestToJoinBoard) => request.status === BOARD_JOIN_REQUEST_STATUS.REQUESTED).length,
      )
    } catch (e) {
      console.warn('Error getting board join requests')
      setJoinRequests([])
      setNewJoinRequests(0)
    }
  }, [boardUuid, setJoinRequests, setNewJoinRequests])

  const removeOnePager = async (onepager: PUBLISHED_BOARD_ONEPAGER) => {
    try {
      await axios.delete(routes.boardOnePagerRemove(boardUuid, onepager.content.onePager.uuid), {
        headers: generateHeaders(),
      })

      toast({
        title: 'Removed OnePager',
        description: `Removed onepager.vc/${onepager.content.onePager.slug}`,
        status: 'success',
        duration: 5000,
        isClosable: true,
        position: 'bottom-left',
      })
      setOnePagersOnBoard(allOpsOnBoard.filter((op) => op.content.onePager.uuid !== onepager.content.onePager.uuid))
      loadOnePagerJoinRequests()
    } catch (e) {
      toast({
        title: 'Error!',
        description: `Error removing onepager.vc/${onepager.content.onePager.slug}`,
        status: 'error',
        duration: 3000,
        isClosable: true,
        position: 'bottom-left',
      })
      console.warn(e)
    }
  }

  const onCSVUpload = async (urls: string[]) => {
    const newOnePagers = []
    let alreadyOnBoardCount = 0
    const totalSlugs = urls.length

    // TODO (update syntax)
    // eslint-disable-next-line no-restricted-syntax
    for (const url of urls) {
      const slug = url.toLowerCase().slice(SIMPLE_APP_URL.length + url.toLowerCase().indexOf(SIMPLE_APP_URL) + 1)
      const isOnBoard = allOpsOnBoard.some((onePagerOnBoard) => onePagerOnBoard.content.onePager.slug === slug)

      if (!isOnBoard) {
        try {
          // eslint-disable-next-line no-await-in-loop
          const response = await axios.post(
            routes.boardOnePagerAdd(boardUuid, slug),
            {},
            { headers: generateHeaders() },
          )
          if (response.data?.data) {
            const { onePager } = response.data.data

            newOnePagers.push(onePager)
          }
        } catch (e) {
          console.warn(e)
        }
      } else {
        alreadyOnBoardCount += 1
      }
    }
    setOnePagersOnBoard(
      allOpsOnBoard.concat(...newOnePagers).sort((op1: PUBLISHED_BOARD_ONEPAGER, op2: PUBLISHED_BOARD_ONEPAGER) => {
        return op1.content.onePager.company_name
          .toLowerCase()
          .localeCompare(op2.content.onePager.company_name.toLowerCase())
      }),
    )
    toast({
      title: 'Added OnePagers!',
      description: `Added ${newOnePagers.length} of ${totalSlugs} OnePager${totalSlugs === 1 ? '' : 's'} to Board.`,
      status: 'success',
      duration: 5000,
      isClosable: true,
      position: 'bottom-left',
    })
    if (alreadyOnBoardCount > 0) {
      toast({
        title: 'Some OnePagers already present',
        description: `${alreadyOnBoardCount} OnePager${
          alreadyOnBoardCount === 1 ? '' : 's'
        } were already on this Board.`,
        status: 'info',
        duration: 5000,
        isClosable: true,
        position: 'bottom-left',
      })
    }
  }

  const onUrlSubmit = handleSubmit(async (search: any) => {
    const url = (search.url as string).toLowerCase()
    if (url.length < 1 || !url.includes(SIMPLE_APP_URL)) {
      toast({
        title: 'Add OnePager Error!',
        description: 'Enter a valid url to add a OnePager.',
        status: 'error',
        duration: 3000,
        isClosable: true,
        position: 'bottom-left',
      })
      return
    }
    const slug = url.slice(SIMPLE_APP_URL.length + url.indexOf(SIMPLE_APP_URL) + 1)
    if (!slug) {
      toast({
        title: 'Add OnePager Error!',
        description: 'Enter a valid url to add a OnePager.',
        status: 'error',
        duration: 3000,
        isClosable: true,
        position: 'bottom-left',
      })
      return
    }

    const isOnBoard = allOpsOnBoard.some((onePagerOnBoard) => onePagerOnBoard.content.onePager.slug === slug)
    if (isOnBoard) {
      toast({
        title: 'OnePager already included!',
        description: 'This OnePager is already on the Board.',
        status: 'error',
        duration: 3000,
        isClosable: true,
        position: 'bottom-left',
      })
    } else {
      try {
        const response = await axios.post(routes.boardOnePagerAdd(boardUuid, slug), {}, { headers: generateHeaders() })
        if (response.data?.data) {
          const { onePager } = response.data.data

          toast({
            title: 'Added OnePager!',
            description: `Added onepager.vc/${slug}`,
            status: 'success',
            duration: 5000,
            isClosable: true,
            position: 'bottom-left',
          })

          setOnePagersOnBoard(
            allOpsOnBoard.concat(onePager).sort((op1: PUBLISHED_BOARD_ONEPAGER, op2: PUBLISHED_BOARD_ONEPAGER) => {
              return op1.content.onePager.company_name
                .toLowerCase()
                .localeCompare(op2.content.onePager.company_name.toLowerCase())
            }),
          )
          loadOnePagerJoinRequests()
        } else {
          toast({
            title: 'OnePager not found',
            status: 'error',
            duration: 3000,
            isClosable: true,
            position: 'bottom-left',
          })
        }
      } catch (e) {
        toast({
          title: 'OnePager not found',
          status: 'error',
          duration: 3000,
          isClosable: true,
          position: 'bottom-left',
        })
      }
    }
  })

  useEffect(() => {
    loadOnePagerJoinRequests()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const AddOnePagers: AddOnePagersModalProps = {
    isOpen: openModal,
    onClose: () => setOpenModal(false),
    onSubmit: () => alert('submitted'),
    boardUuid,
    onePagersOnBoard: allOpsOnBoard,
    setOnePagersOnBoard,
  }

  return (
    <>
      <OnePagersCSVUploadModal onClose={onClose} isOpen={isOpen} onSubmit={onCSVUpload} />
      <BoardJoinRequestsModal
        onClose={onJoinRequestsModalClose}
        isOpen={isJoinRequestsModalOpen}
        reloadRequests={loadOnePagerJoinRequests}
        requests={joinRequests}
        boardUuid={boardUuid}
        allOpsOnBoard={allOpsOnBoard}
        setOnePagersOnBoard={setOnePagersOnBoard}
      />
      <Card w="100%" overflow="initial" mt="2rem" position="relative">
        <CardHeader title="OnePagers on this Board" />
        <Box alignItems="center" ml="16px" px="1rem">
          <Flex w="100%" alignItems="center" justifyContent="flex-start">
            <Flex w="40%">
              <ControlledTextInput
                name="url"
                id="url"
                type="text"
                label="Add OnePager by link"
                placeholder={`${APP_URL!.replace(/http:\/\/|https:\/\//, '')}/example`}
                rhfControl={control}
                onKeyDown={(e: any) => {
                  if (e.keyCode === 13) {
                    onUrlSubmit()
                  }
                }}
              />
            </Flex>
            <Button
              ml="1rem"
              mt="1rem"
              w="150px"
              onClick={() => onUrlSubmit()}
              mb="1rem"
              backgroundColor="white"
              color="black"
              variant="outline"
            >
              Add OnePager
            </Button>
            <Button
              ml="1rem"
              mt="1rem"
              onClick={onJoinRequestsModalOpen}
              mb="1rem"
              backgroundColor="white"
              color="black"
              variant="outline"
              position="relative"
            >
              Review Join Requests
              {newJoinRequests > 0 && (
                <Box
                  position="absolute"
                  fontSize="10px"
                  w="16px"
                  h="16px"
                  top="-5px"
                  right="-5px"
                  bgColor="red.500"
                  textColor="white"
                  rounded="full"
                  display="flex"
                  alignItems="center"
                  justifyContent="center"
                >
                  {newJoinRequests}
                </Box>
              )}
            </Button>
            <Box flexGrow={1} />
            <Button
              leftIcon={<FaArrowUp />}
              ml="1rem"
              mt="1rem"
              w="150px"
              mb="1rem"
              backgroundColor="white"
              color="black"
              variant="outline"
              onClick={onOpen}
            >
              Add Via CSV
            </Button>
          </Flex>
          {showSearch && (
            <Box d="flex" justifyContent="center" onClick={() => setOpenModal(true)}>
              <Button variant="link" color="gray.800">
                or Search for OnePagers
              </Button>
            </Box>
          )}
        </Box>
        <Divider />
        {allOpsOnBoard.map((op: PUBLISHED_BOARD_ONEPAGER) => {
          return (
            <OnePagerBoardRowCard
              key={op.content.onePager.uuid}
              op={{ ...op.content.onePager, role_information: op.content.role_information }}
              opCategories={op.content.categories}
              onRemove={() => removeOnePager(op)}
              isBuilder
              _hover={{
                transform: 'none',
              }}
            />
          )
        })}
      </Card>

      <AddOnePagersModal {...AddOnePagers} />
    </>
  )
}

export default AvailableOnePagers
```
